fn max_of_list(lst: &Vec<usize>) -> usize {
    // Since the vector is non-empty, we can safely take the first element as an initial max.
    let mut max_val = lst[0];

    // Iterate through the rest of the elements, updating max_val when we find a larger one.
    for &v in lst.iter().skip(1) {
        if v > max_val {
            max_val = v;
        }
    }

    max_val
}

